1	import type { LearnerState, SrsCard } from "../../domain/shared/types";
2	import { INITIAL_LEARNER_STATE } from "../../domain/shared/types";
3	import { LAPSE_RECOVERY_INTERVAL_MINUTES } from "../../domain/srs/value-objects/SrsSchedule";
4	import { mergeLearnerStates } from "./MergeService";
5	import { validateLearnerState } from "./Validation";
6	
7	interface LegacySrsData {
8		easeFactor: number;
9		interval: number;
10		repetitions: number;
11		learningStep?: number | null;
12		nextReviewDate: string;
13		lastReviewDate: string | null;
14		lapseCount?: number;
15	}
16	
17	function migrateSrsCard(card: SrsCard, now: string): void {
18		const srs = card.srs as LegacySrsData;
19		if (srs.learningStep === undefined) {
20			srs.learningStep = null;
21		}
22		if (srs.lapseCount === undefined) {
23			srs.lapseCount = 0;
24		}
25		// A card stuck mid-relearning from a lapse recorded under the old
26		// multi-step relearning ladder (2-3 more correct answers required to
27		// re-graduate) — fast-forward it back to graduated now that a lapse no
28		// longer re-enters that ladder. A brand-new item still climbing its
29		// first-ever learning ladder always has lapseCount 0 (only
30		// handleGraduatedPhase increments it), so this never touches those.
31		if (srs.lapseCount > 0 && srs.learningStep !== null) {
32			srs.learningStep = null;
33			srs.interval = LAPSE_RECOVERY_INTERVAL_MINUTES;
34			srs.nextReviewDate = new Date(
35				new Date(now).getTime() + LAPSE_RECOVERY_INTERVAL_MINUTES * 60_000,
36			).toISOString();
37		}
38	}
39	
40	export function migrateState(
41		state: LearnerState,
42		now: string = new Date().toISOString(),
43	): LearnerState {
44		for (const card of Object.values(state.cards)) {
45			migrateSrsCard(card, now);
46		}
47		for (const card of Object.values(state.vocabCards ?? {})) {
48			migrateSrsCard(card, now);
49			// Migrate legacy wordThai → promptWord
50			const legacy = card as unknown as Record<string, unknown>;
51			if ("wordThai" in legacy && !("promptWord" in legacy)) {
52				legacy.promptWord = legacy.wordThai;
53				delete legacy.wordThai;
54			}
55		}
56		for (const card of Object.values(state.grammarCards ?? {})) {
57			migrateSrsCard(card, now);
58		}
59		for (const card of Object.values(state.sentenceCards ?? {})) {
60			migrateSrsCard(card, now);
61		}
62		return state;
63	}
64	
65	export interface IStorage {
66		load(): LearnerState;
67		save(state: LearnerState): void;
68		reset(): void;
69		exportData(): string;
70		importData(json: string): void;
71	}
72	
73	export class InMemoryStorage implements IStorage {
74		private state: LearnerState = structuredClone(INITIAL_LEARNER_STATE);
75	
76		load(): LearnerState {
77			return structuredClone(this.state);
78		}
79	
80		save(state: LearnerState): void {
81			this.state = structuredClone(state);
82		}
83	
84		reset(): void {
85			this.state = structuredClone(INITIAL_LEARNER_STATE);
86		}
87	
88		exportData(): string {
89			return JSON.stringify(this.state);
90		}
91	
92		importData(json: string): void {
93			const parsed: unknown = JSON.parse(json);
94			if (!validateLearnerState(parsed)) {
95				throw new Error("Invalid progress file format");
96			}
97			this.state = mergeLearnerStates(this.state, parsed as LearnerState);
98		}
99	}
100	
101	export class LocalStorageAdapter implements IStorage {
102		private readonly key: string;
103	
104		/**
105		 * The parsed state, memoized against the exact raw string it came from.
106		 *
107		 * Without it every repository method re-ran `JSON.parse` + `migrateState`
108		 * over the whole learner state. Because pages call use cases directly
109		 * from their render bodies, one Dashboard render did that 42 times —
110		 * ~12 MB of JSON parsed for a single render, and ~5 MB more on every
111		 * answered card via the `Layout` shell's re-render. That was the app's
112		 * dominant CPU cost on a phone.
113		 *
114		 * `getItem` is still called every time and the result compared, so a
115		 * write that bypasses this adapter (another tab, a test seeding the key
116		 * directly, devtools) is still picked up exactly as before — the cache
117		 * changes how fast a load is, never what it observes.
118		 *
119		 * The cached object is returned **live, not cloned**: cloning costs more
120		 * than the parse it replaces (measured: `structuredClone` 0.79 ms vs
121		 * `JSON.parse` 0.57 ms on a 282 KB state). That is sound because every
122		 * caller here either only reads, or follows the load-mutate-save shape
123		 * the repositories use, where mutating then saving is the intended
124		 * effect. Note this differs from `InMemoryStorage`, which clones on both
125		 * ends.
126		 */
127		private cache: LearnerState | null = null;
128		/** The exact `getItem` string `cache` was parsed from. */
129		private cacheRaw: string | null = null;
130	
131		constructor(key = "thai-srs-state") {
132			this.key = key;
133		}
134	
135		load(): LearnerState {
136			if (typeof localStorage === "undefined") {
137				return structuredClone(INITIAL_LEARNER_STATE);
138			}
139			const raw = localStorage.getItem(this.key);
140			if (raw !== null && raw === this.cacheRaw && this.cache) {
141				return this.cache;
142			}
143			if (!raw) {
144				this.cache = null;
145				this.cacheRaw = null;
146				return structuredClone(INITIAL_LEARNER_STATE);
147			}
148			const state = JSON.parse(raw) as LearnerState;
149			if (!state.vocabCards) {
150				state.vocabCards = {};
151			}
152			if (!state.grammarCards) {
153				state.grammarCards = {};
154			}
155			if (!state.sentenceCards) {
156				state.sentenceCards = {};
157			}
158			if (!state.achievements) {
159				state.achievements = [];
160			}
161			this.cache = migrateState(state);
162			this.cacheRaw = raw;
163			return this.cache;
164		}
165	
166		save(state: LearnerState): void {
167			const raw = JSON.stringify(state);
168			// Adopt what was just saved as the cache, keyed on the very string
169			// written, so the next `load` is a string compare rather than a parse.
170			this.cache = state;
171			this.cacheRaw = raw;
172			if (typeof localStorage === "undefined") return;
173			localStorage.setItem(this.key, raw);
174		}
175	
176		reset(): void {
177			this.cache = null;
178			this.cacheRaw = null;
179			if (typeof localStorage === "undefined") return;
180			localStorage.removeItem(this.key);
181		}
182	
183		exportData(): string {
184			return JSON.stringify(this.load());
185		}
186	
187		importData(json: string): void {
188			const parsed: unknown = JSON.parse(json);
189			if (!validateLearnerState(parsed)) {
190				throw new Error("Invalid progress file format");
191			}
192			const merged = mergeLearnerStates(this.load(), parsed as LearnerState);
193			this.save(merged);
194		}
195	}
196

