		property: PropertyType | "toneRule";
		lessonNumber: number;
		audioUrl?: string;
		consonantClass?: string;
	}): ScriptPropertyCard {
		return new ScriptPropertyCard(
			dto.id,
			dto.question,
			dto.correctAnswer,
			dto.choices,
