300		 *
301		 * A card id that's genuinely new (not just patched) is recorded as a
302		 * pending catch-up for its lesson, so the learner gets a one-time intro
303		 * to it instead of it appearing cold in review — see `getPendingCatchUps`.
304		 */
305		reconcileCards(): void {
306			const persisted = (
307				this.cardRepo.findAll("script") as ScriptPropertyCard[]
308			).map((card) => card.toDTO() as PropertyCard);
309			const persistedIds = new Set(persisted.map((card) => card.id));
310			const generated = this.stateRepo
311				.getCompletedLessons()
312				.flatMap((lessonNumber) => generateCardsForLesson(lessonNumber));
313	
314			const newlyBackfilled = generated.filter(
315				(card) => !persistedIds.has(card.id),
316			);
317			const newIdsByLesson = new Map<number, string[]>();
318			for (const card of newlyBackfilled) {
319				const ids = newIdsByLesson.get(card.lessonNumber) ?? [];
320				ids.push(card.id);
321				newIdsByLesson.set(card.lessonNumber, ids);
322			}
323			for (const [lessonNumber, cardIds] of newIdsByLesson) {
324				this.stateRepo.addPendingCatchUp(lessonNumber, cardIds);
325			}
326	
327			const toSave = reconcileGeneratedCards(persisted, generated);
328			if (toSave.length === 0) return;
329	
330			this.cardRepo.saveAll(toSave.map(toEntity));
331		}
