340			lessonNumber: number;
341			summary: LessonSummary;
342		}> {
343			const allCards = this.cardRepo.findAll("script") as ScriptPropertyCard[];
344	
345			return this.stateRepo
346				.getPendingCatchUps()
347				.map(({ lessonNumber, cardIds }) => {
348					const idSet = new Set(cardIds);
349					// A tone rule card has no glyph (`symbolCharacter` is ""), so it's
350					// keyed by its own card id instead, which is exactly the id
351					// `getLessonSummary` puts on `ToneRuleSummary.id`.
352					const newKeys = new Set(
353						allCards
354							.filter((card) => idSet.has(card.id))
355							.map((card) => card.symbolCharacter || card.id),
356					);
357					const full = this.getLessonSummary(lessonNumber);
358					return {
359						lessonNumber,
360						summary: {
361							...full,
362							videoUrl: undefined,
363							consonants: full.consonants.filter((c) => newKeys.has(c.character)),
364							vowels: full.vowels.filter((v) => newKeys.has(v.character)),
365							toneMarks: full.toneMarks.filter((t) => newKeys.has(t.character)),
366							rareVowels: full.rareVowels.filter((v) => newKeys.has(v.character)),
367							numerals: full.numerals.filter((n) => newKeys.has(n.character)),
368							toneRules: full.toneRules.filter((r) => newKeys.has(r.id)),
369						},
370					};
371				});
372		}
