374		/** The actual review cards (with live SRS state) for a pending catch-up. */
375		getPendingCatchUpCards(lessonNumber: number): PropertyCard[] {
376			const pending = this.stateRepo
377				.getPendingCatchUps()
378				.find((p) => p.lessonNumber === lessonNumber);
379			if (!pending) return [];
380	
381			const idSet = new Set(pending.cardIds);
382			return (this.cardRepo.findAll("script") as ScriptPropertyCard[])
383				.filter((card) => idSet.has(card.id))
384				.map((card) => card.toDTO() as PropertyCard);
385		}
