import type { CardRepository } from "../../ports/CardRepository";
import type { LearnerStateRepository } from "../../ports/LearnerStateRepository";
import type { ApprenticeService } from "../../shared/services/ApprenticeService";
import { reconcileGeneratedCards } from "../../shared/services/reconcileCards";
import type { PropertyCard } from "../../shared/types";
import { SrsSchedule } from "../../srs/value-objects/SrsSchedule";
import {
	getSymbolsByLesson,
	lessons,
	rareVowels,
	ThaiConsonant,
	ThaiToneMark,
	ThaiVowel,
	thaiNumerals,
	toneMarkRules,
	toneRules,
} from "../data/symbols";
import { ScriptPropertyCard } from "../entities/ScriptPropertyCard";
import { generateCardsForLesson } from "./ScriptCardGenerator";

const TOTAL_LESSONS = 25;

export interface LessonInfo {
	lessonNumber: number;
	title: string;
	focus: string;
	cards: PropertyCard[];
}

export interface ConsonantSummary {
	character: string;
	name: string;
	nameRomanized: string;
	nameMeaning: string;
	classType: string;
	initialSound: string;
	finalSound: string;
	hasDeadEnding: boolean;
	isAspirated: boolean;
	mnemonic?: string;
	audioUrl?: string;
}

export interface VowelSummary {
	character: string;
	name: string;
	sound: string;
	length: string;
	position: string;
	mnemonic?: string;
	audioUrl?: string;
}

export interface ToneMarkSummary {
	character: string;
	name: string;
	midClassTone: string;
	highClassTone: string | null;
	lowClassTone: string | null;
	audioUrl?: string;
}

export interface RareVowelSummary {
	character: string;
	name: string;
	pronunciation: string;
	length: string;
	notes: string;
}

export interface NumeralSummary {
	character: string;
	arabic: number;
	word: string;
	romanization: string;
}

export interface ToneRuleSummary {
	id: string;
	description: string;
}

export interface LessonSummary {
	lessonNumber: number;
	title: string;
	focus: string;
	videoUrl?: string;
	consonants: ConsonantSummary[];
	vowels: VowelSummary[];
	toneMarks: ToneMarkSummary[];
	rareVowels: RareVowelSummary[];
	numerals: NumeralSummary[];
	toneRules: ToneRuleSummary[];
}

function toEntity(dto: PropertyCard): ScriptPropertyCard {
	return new ScriptPropertyCard(
		dto.id,
		dto.question,
		dto.correctAnswer,
		dto.choices,
		SrsSchedule.fromDTO(dto.srs),
		dto.symbolCharacter,
		dto.property,
		dto.lessonNumber,
		dto.audioUrl,
		dto.consonantClass,
	);
}

export class LearningService {
	constructor(
		private readonly cardRepo: CardRepository,
		private readonly stateRepo: LearnerStateRepository,
		private readonly apprenticeService?: ApprenticeService,
	) {}

	startLesson(lessonNumber: number): LessonInfo | null {
		if (
			this.apprenticeService &&
			!this.apprenticeService.canStartLesson("script")
		) {
			return null;
		}

		const completedLessons = this.stateRepo.getCompletedLessons();

		if (completedLessons.includes(lessonNumber)) {
			throw new Error(`Lesson ${lessonNumber} is already completed`);
		}

		for (let i = 1; i < lessonNumber; i++) {
			if (!completedLessons.includes(i)) {
				throw new Error(
					`Must complete lesson ${i} before starting lesson ${lessonNumber}`,
				);
			}
		}

		const lessonMeta = lessons.find((l) => l.number === lessonNumber);
		if (!lessonMeta) throw new Error(`Lesson ${lessonNumber} not found`);

		const cards = generateCardsForLesson(lessonNumber);
		const entities = cards.map(toEntity);

		this.cardRepo.saveAll(entities);
		this.stateRepo.setCurrentLesson(lessonNumber);

		return {
			lessonNumber,
			title: lessonMeta.title,
			focus: lessonMeta.focus,
			cards,
		};
	}

	completeLesson(lessonNumber: number): void {
		this.stateRepo.addCompletedLesson(lessonNumber);

		if (this.stateRepo.getCurrentLesson() === lessonNumber) {
			this.stateRepo.setCurrentLesson(null);
		}
	}

	unlearnLesson(lessonNumber: number): void {
		this.stateRepo.removeCompletedLesson(lessonNumber);

		const allCards = this.cardRepo.findAll("script") as ScriptPropertyCard[];
		for (const card of allCards) {
			if (card.lessonNumber === lessonNumber) {
				this.cardRepo.remove(card.id, "script");
			}
		}

		if (this.stateRepo.getCurrentLesson() === lessonNumber) {
			this.stateRepo.setCurrentLesson(null);
		}
	}

	getNextLesson(): number | null {
		const completedLessons = this.stateRepo.getCompletedLessons();
		for (let i = 1; i <= TOTAL_LESSONS; i++) {
			if (!completedLessons.includes(i)) return i;
		}
		return null;
	}

	getLessonSummary(lessonNumber: number): LessonSummary {
		const lessonMeta = lessons.find((l) => l.number === lessonNumber);
		if (!lessonMeta) throw new Error(`Lesson ${lessonNumber} not found`);

		const symbols = getSymbolsByLesson(lessonNumber);

		return {
			lessonNumber,
			title: lessonMeta.title,
			focus: lessonMeta.focus,
			videoUrl: lessonMeta.videoUrl,
			consonants: symbols
				.filter((s): s is ThaiConsonant => s instanceof ThaiConsonant)
				.map((c) => ({
					character: c.character,
					name: c.name,
					nameRomanized: c.nameRomanized,
					nameMeaning: c.nameMeaning,
					classType: c.classType,
					initialSound: c.initialSound,
					finalSound: c.finalSound,
					hasDeadEnding: c.hasDeadEnding,
					isAspirated: c.isAspirated,
					mnemonic: c.mnemonic,
					audioUrl: c.audioUrl,
				})),
			vowels: symbols
				.filter((s): s is ThaiVowel => s instanceof ThaiVowel)
				.map((v) => ({
					character: v.character,
					name: v.name,
					sound: v.sound,
					length: v.length,
					position: v.position,
					mnemonic: v.mnemonic,
					audioUrl: v.audioUrl,
				})),
			toneMarks: symbols
				.filter((s): s is ThaiToneMark => s instanceof ThaiToneMark)
				.map((t) => ({
					character: t.character,
					name: t.name,
					midClassTone: t.midClassTone,
					highClassTone: t.highClassTone,
					lowClassTone: t.lowClassTone,
					audioUrl: t.audioUrl,
				})),
			rareVowels: rareVowels
				.filter((v) => v.lesson === lessonNumber)
				.map((v) => ({
					character: v.character,
					name: v.name,
					pronunciation: v.pronunciation,
					length: v.length,
					notes: v.notes,
				})),
			numerals: thaiNumerals
				.filter((n) => n.lesson === lessonNumber)
				.map((n) => ({
					character: n.thai,
					arabic: n.arabic,
					word: n.word,
					romanization: n.romanization,
				})),
			toneRules: [
				...toneRules
					.filter((r) => r.lesson === lessonNumber)
					.map((r) => ({
						id: `tone-rule:${r.id}`,
						description: r.description,
					})),
				...toneMarkRules
					.filter((r) => r.lesson === lessonNumber)
					.map((r) => ({
						id: `tone-mark-rule:${r.toneMarkName}-${r.consonantClass}`,
						description: `${r.toneMarkName} on ${r.consonantClass} class = ${r.resultingTone} tone`,
					})),
			],
		};
	}

	getCompletedLessons(): number[] {
		return this.stateRepo.getCompletedLessons();
	}

	getLessonMasteryProgress(lessonNumber: number): {
		total: number;
		graduated: number;
		percentage: number;
	} {
		const allCards = this.cardRepo.findAll("script") as ScriptPropertyCard[];
		const lessonCards = allCards.filter((c) => c.lessonNumber === lessonNumber);
		const total = lessonCards.length;
		const graduated = lessonCards.filter(
			(c) => !c.schedule.isInLearning,
		).length;
		return {
			total,
			graduated,
			percentage: total === 0 ? 0 : graduated / total,
		};
	}

	isNextLessonAvailable(): boolean {
		return this.getNextLesson() !== null;
	}

	/**
	 * Backfills already-completed lessons with any card the current generator
	 * would now produce for them that isn't persisted yet, or an `audioUrl`
	 * on a persisted card that previously had none. See
	 * `reconcileGeneratedCards` for the exact, deliberately narrow rules.
	 *
	 * A card id that's genuinely new (not just patched) is recorded as a
	 * pending catch-up for its lesson, so the learner gets a one-time intro
	 * to it instead of it appearing cold in review — see `getPendingCatchUps`.
	 */
	reconcileCards(): void {
		const persisted = (
			this.cardRepo.findAll("script") as ScriptPropertyCard[]
		).map((card) => card.toDTO() as PropertyCard);
		const persistedIds = new Set(persisted.map((card) => card.id));
		const generated = this.stateRepo
			.getCompletedLessons()
			.flatMap((lessonNumber) => generateCardsForLesson(lessonNumber));

		const newlyBackfilled = generated.filter(
			(card) => !persistedIds.has(card.id),
		);
		const newIdsByLesson = new Map<number, string[]>();
		for (const card of newlyBackfilled) {
			const ids = newIdsByLesson.get(card.lessonNumber) ?? [];
			ids.push(card.id);
			newIdsByLesson.set(card.lessonNumber, ids);
		}
		for (const [lessonNumber, cardIds] of newIdsByLesson) {
			this.stateRepo.addPendingCatchUp(lessonNumber, cardIds);
		}

		const toSave = reconcileGeneratedCards(persisted, generated);
		if (toSave.length === 0) return;

		this.cardRepo.saveAll(toSave.map(toEntity));
	}

	/**
	 * Already-completed lessons that gained new content since the learner
	 * finished them (e.g. a symbol category wired up after the fact), scoped
	 * down to just the new items so `LessonIntro` can walk through them
	 * without repeating what was already taught.
	 */
	getPendingCatchUps(): Array<{
		lessonNumber: number;
		summary: LessonSummary;
	}> {
		const allCards = this.cardRepo.findAll("script") as ScriptPropertyCard[];

		return this.stateRepo
			.getPendingCatchUps()
			.map(({ lessonNumber, cardIds }) => {
				const idSet = new Set(cardIds);
				// A tone rule card has no glyph (`symbolCharacter` is ""), so it's
				// keyed by its own card id instead, which is exactly the id
				// `getLessonSummary` puts on `ToneRuleSummary.id`.
				const newKeys = new Set(
					allCards
						.filter((card) => idSet.has(card.id))
						.map((card) => card.symbolCharacter || card.id),
				);
				const full = this.getLessonSummary(lessonNumber);
				return {
					lessonNumber,
					summary: {
						...full,
						videoUrl: undefined,
						consonants: full.consonants.filter((c) => newKeys.has(c.character)),
						vowels: full.vowels.filter((v) => newKeys.has(v.character)),
						toneMarks: full.toneMarks.filter((t) => newKeys.has(t.character)),
						rareVowels: full.rareVowels.filter((v) => newKeys.has(v.character)),
						numerals: full.numerals.filter((n) => newKeys.has(n.character)),
						toneRules: full.toneRules.filter((r) => newKeys.has(r.id)),
					},
				};
			});
	}

	/** The actual review cards (with live SRS state) for a pending catch-up. */
	getPendingCatchUpCards(lessonNumber: number): PropertyCard[] {
		const pending = this.stateRepo
			.getPendingCatchUps()
			.find((p) => p.lessonNumber === lessonNumber);
		if (!pending) return [];

		const idSet = new Set(pending.cardIds);
		return (this.cardRepo.findAll("script") as ScriptPropertyCard[])
			.filter((card) => idSet.has(card.id))
			.map((card) => card.toDTO() as PropertyCard);
	}

	/** Marks a pending catch-up as seen once the learner completes its intro. */
	dismissPendingCatchUp(lessonNumber: number): void {
		this.stateRepo.clearPendingCatchUp(lessonNumber);
	}
}

