1	import { beforeEach, describe, expect, it } from "vitest";
2	import { InMemoryStorage } from "../../../infrastructure/persistence/Storage";
3	import { StorageCardRepository } from "../../../infrastructure/persistence/StorageCardRepository";
4	import { StorageLearnerStateRepository } from "../../../infrastructure/persistence/StorageLearnerStateRepository";
5	import { ReviewService } from "../../session/services/ReviewService";
6	import {
7		ApprenticeService,
8		MAX_SCRIPT_APPRENTICE_ITEMS,
9	} from "../../shared/services/ApprenticeService";
10	import type { SrsData } from "../../shared/types";
11	import { RecallRating } from "../../srs/value-objects/RecallRating";
12	import { LearningService } from "./ScriptLessonService";
13	
14	describe("LearningService", () => {
15		let service: LearningService;
16		let storage: InMemoryStorage;
17		let cardRepo: StorageCardRepository;
18		let stateRepo: StorageLearnerStateRepository;
19	
20		beforeEach(() => {
21			storage = new InMemoryStorage();
22			cardRepo = new StorageCardRepository(storage);
23			stateRepo = new StorageLearnerStateRepository(storage);
24			service = new LearningService(cardRepo, stateRepo);
25		});
26	
27		describe("startLesson", () => {
28			it("starts lesson 1 and generates cards", () => {
29				const lesson = service.startLesson(1);
30				expect(lesson).not.toBeNull();
31				expect(lesson?.lessonNumber).toBe(1);
32				expect(lesson?.cards.length).toBeGreaterThan(0);
33			});
34	
35			it("persists cards to storage", () => {
36				service.startLesson(1);
37				const state = storage.load();
38				expect(Object.keys(state.cards).length).toBeGreaterThan(0);
39			});
40	
41			it("sets currentLesson in state", () => {
42				service.startLesson(1);
43				const state = storage.load();
44				expect(state.currentLesson).toBe(1);
45			});
46	
47			it("throws if lesson is already completed", () => {
48				service.startLesson(1);
49				service.completeLesson(1);
50				expect(() => service.startLesson(1)).toThrow();
51			});
52	
53			it("requires sequential lessons (cannot skip)", () => {
54				expect(() => service.startLesson(3)).toThrow();
55			});
56		});
57	
58		describe("completeLesson", () => {
59			it("marks lesson as completed", () => {
60				service.startLesson(1);
61				service.completeLesson(1);
62				const state = storage.load();
63				expect(state.completedLessons).toContain(1);
64				expect(state.currentLesson).toBeNull();
65			});
66		});
67	
68		describe("unlearnLesson", () => {
69			it("removes lesson and its cards from state", () => {
70				service.startLesson(1);
71				service.completeLesson(1);
72				service.unlearnLesson(1);
73				const state = storage.load();
74				expect(state.completedLessons).not.toContain(1);
75				const lesson1Cards = Object.values(state.cards).filter(
76					(c) => c.lessonNumber === 1,
77				);
78				expect(lesson1Cards).toHaveLength(0);
79			});
80		});
81	
82		describe("getNextLesson", () => {
83			it("returns 1 when no lessons completed", () => {
84				expect(service.getNextLesson()).toBe(1);
85			});
86	
87			it("returns 2 after lesson 1 completed", () => {
88				service.startLesson(1);
89				service.completeLesson(1);
90				expect(service.getNextLesson()).toBe(2);
91			});
92	
93			it("returns null after all 25 lessons completed", () => {
94				const _reviewService = new ReviewService(cardRepo, stateRepo);
95				for (let i = 1; i <= 25; i++) {
96					service.startLesson(i);
97					service.completeLesson(i);
98					// Graduate all cards for this lesson so mastery gate passes
99					const state = storage.load();
100					for (const card of Object.values(state.cards)) {
101						if (card.lessonNumber === i && card.srs.learningStep !== null) {
102							card.srs.learningStep = null;
103							card.srs.interval = 4320;
104						}
105					}
106					storage.save(state);
107				}
108				expect(service.getNextLesson()).toBeNull();
109			});
110		});
111	
112		describe("getLessonSummary", () => {
113			it("returns lesson with symbol info for a given lesson number", () => {
114				const summary = service.getLessonSummary(1);
115				expect(summary.lessonNumber).toBe(1);
116				expect(summary.consonants.length).toBeGreaterThan(0);
117			});
118	
119			it("includes rare vowels for lesson 22", () => {
120				const summary = service.getLessonSummary(22);
121				expect(summary.rareVowels.map((v) => v.character)).toEqual([
122					"ฤ",
123					"ฤๅ",
124					"ฦ",
125					"ฦๅ",
126				]);
127			});
128	
129			it("includes numerals for lesson 23", () => {
130				const summary = service.getLessonSummary(23);
131				expect(summary.numerals.map((n) => n.character)).toEqual(["๑", "๒", "๓"]);
132			});
133	
134			it("includes tone rule ids matching their generated card ids", () => {
135				const summary = service.getLessonSummary(2);
136				expect(summary.toneRules).toEqual([
137					{ id: "tone-rule:low-live", description: expect.any(String) },
138				]);
139			});
140	
141			it("includes tone mark rule ids matching their generated card ids", () => {
142				const summary = service.getLessonSummary(17);
143				const ids = summary.toneRules.map((r) => r.id);
144				expect(ids).toContain("tone-mark-rule:mai ek-mid");
145				expect(ids).toContain("tone-mark-rule:mai tho-mid");
146			});
147		});
148	
149		describe("mastery gating", () => {
150			function graduateAllCards(
151				store: InMemoryStorage,
152				lessonNumber: number,
153			): void {
154				const state = store.load();
155				for (const card of Object.values(state.cards)) {
156					if (card.lessonNumber === lessonNumber) {
157						card.srs.learningStep = null;
158						card.srs.interval = 4320;
159					}
160				}
161				store.save(state);
162			}
163	
164			it("lesson 1 is always available via isNextLessonAvailable", () => {
165				expect(service.isNextLessonAvailable()).toBe(true);
166			});
167	
168			it("startLesson allows lesson 2 after completing lesson 1", () => {
169				service.startLesson(1);
170				service.completeLesson(1);
171				expect(service.startLesson(2)).not.toBeNull();
172			});
173	
174			it("getLessonMasteryProgress returns correct total/graduated/percentage", () => {
175				service.startLesson(1);
176				service.completeLesson(1);
177	
178				const beforeProgress = service.getLessonMasteryProgress(1);
179				expect(beforeProgress.total).toBeGreaterThan(0);
180				expect(beforeProgress.graduated).toBe(0);
181				expect(beforeProgress.percentage).toBe(0);
182	
183				// Graduate all cards
184				graduateAllCards(storage, 1);
185	
186				const afterProgress = service.getLessonMasteryProgress(1);
187				expect(afterProgress.graduated).toBe(afterProgress.total);
188				expect(afterProgress.percentage).toBe(1);
189			});
190	
191			it("startLesson succeeds when previous lesson is mastered", () => {
192				service.startLesson(1);
193				service.completeLesson(1);
194				graduateAllCards(storage, 1);
195	
196				const lesson2 = service.startLesson(2);
197				expect(lesson2).not.toBeNull();
198				expect(lesson2?.lessonNumber).toBe(2);
199			});
200	
201			it("isNextLessonAvailable returns true after completing lessons", () => {
202				service.startLesson(1);
203				service.completeLesson(1);
204				service.startLesson(2);
205				service.completeLesson(2);
206				service.startLesson(3);
207				service.completeLesson(3);
208				expect(service.isNextLessonAvailable()).toBe(true);
209			});
210		});
211	
212		describe("apprentice gating", () => {
213			function makeSrsData(overrides: Partial<SrsData> = {}): SrsData {
214				return {
215					easeFactor: 2.0,
216					interval: 10,
217					repetitions: 0,
218					learningStep: 1,
219					nextReviewDate: new Date().toISOString(),
220					lastReviewDate: null,
221					lapseCount: 0,
222					...overrides,
223				};
224			}
225	
226			it("returns null when ApprenticeService says at script limit", () => {
227				const apprenticeService = new ApprenticeService(cardRepo);
228	
229				const state = storage.load();
230				// Fill up the script apprentice stage to MAX_SCRIPT_APPRENTICE_ITEMS
231				for (let i = 0; i < MAX_SCRIPT_APPRENTICE_ITEMS; i++) {
232					state.cards[`s${i}`] = {
233						id: `s${i}`,
234						question: "test",
235						correctAnswer: "test",
236						choices: ["test"],
237						srs: makeSrsData({ learningStep: 1 }),
238						symbolCharacter: "ก",
239						property: "recognition",
240						lessonNumber: 1,
241					};
242				}
243				storage.save(state);
244	
245				const gatedService = new LearningService(
246					cardRepo,
247					stateRepo,
248					apprenticeService,
249				);
250				const result = gatedService.startLesson(1);
251				expect(result).toBeNull();
252			});
253	
254			it("works normally without ApprenticeService (backward compat)", () => {
255				const result = service.startLesson(1);
256				expect(result).not.toBeNull();
257				expect(result?.lessonNumber).toBe(1);
258			});
259		});
260	
261		describe("reconcileCards", () => {
262			it("backfills a persisted card's audioUrl once completed lessons regain it, without touching other cards' srs", () => {
263				service.startLesson(1);
264				service.completeLesson(1);
265	
266				const persistedBefore = cardRepo.findAll("script");
267				expect(persistedBefore.length).toBeGreaterThan(0);
268				const targetBefore = persistedBefore.find((c) => c.audioUrl);
269				if (!targetBefore) {
270					throw new Error("expected at least one card with audioUrl");
271				}
272				const targetId = targetBefore.id;
273				const realAudioUrl = targetBefore.audioUrl;
274	
275				// Simulate the card having been persisted before it had audio.
276				const state = storage.load();
277				const raw = state.cards[targetId] as { audioUrl?: string };
278				raw.audioUrl = undefined;
279				storage.save(state);
280	
281				// Give it a review history distinct from a fresh card, from a fresh
282				// domain instance that reflects the audioUrl-less storage above.
283				const target = cardRepo.findById(targetId, "script");
284				if (!target) throw new Error("expected card to still exist");
285				target.recordReview(RecallRating.GOOD, new Date().toISOString());
286				cardRepo.save(target);
287				const ratedRepetitions = target.schedule.repetitions;
288				expect(ratedRepetitions).toBeGreaterThan(0);
289				expect(
290					cardRepo.findAll("script").find((c) => c.id === targetId)?.audioUrl,
291				).toBeUndefined();
292	
293				service.reconcileCards();
294	
295				const persistedAfter = cardRepo.findAll("script");
296				const patched = persistedAfter.find((c) => c.id === target.id);
297				expect(patched?.audioUrl).toBe(realAudioUrl);
298				expect(patched?.schedule.repetitions).toBe(ratedRepetitions);
299	
300				// An untouched sibling card is unaffected.
301				const sibling = persistedAfter.find((c) => c.id !== target.id);
302				expect(sibling?.schedule.repetitions).toBe(0);
303			});
304	
305			it("is a no-op when no lessons are completed", () => {
306				service.reconcileCards();
307	
308				expect(cardRepo.findAll("script")).toHaveLength(0);
309			});
310		});
311	
312		describe("pending catch-ups", () => {
313			function completeLessonsUpTo(n: number): void {
314				for (let i = 1; i <= n; i++) {
315					service.startLesson(i);
316					service.completeLesson(i);
317				}
318			}
319	
320			function deleteCardsStartingWith(prefix: string): void {
321				const state = storage.load();
322				for (const id of Object.keys(state.cards)) {
323					if (id.startsWith(prefix)) delete state.cards[id];
324				}
325				storage.save(state);
326			}
327	
328			it("has nothing pending before any reconcile runs", () => {
329				completeLessonsUpTo(22);
330				expect(service.getPendingCatchUps()).toHaveLength(0);
331			});
332	
333			it("flags a pending catch-up scoped to just the backfilled items", () => {
334				completeLessonsUpTo(22);
335				// Simulate lesson 22 having been completed before rare vowels were
336				// wired into card generation.
337				deleteCardsStartingWith("ฤ:");
338				deleteCardsStartingWith("ฤๅ:");
339				deleteCardsStartingWith("ฦ:");
340				deleteCardsStartingWith("ฦๅ:");
341	
342				service.reconcileCards();
343	
344				const pending = service.getPendingCatchUps();
345				expect(pending).toHaveLength(1);
346				expect(pending[0]?.lessonNumber).toBe(22);
347				expect(pending[0]?.summary.rareVowels.map((v) => v.character)).toEqual([
348					"ฤ",
349					"ฤๅ",
350					"ฦ",
351					"ฦๅ",
352				]);
353				// Consonants ฃ, ฅ, ฌ from the same lesson were never removed, so
354				// they aren't part of the catch-up.
355				expect(pending[0]?.summary.consonants).toHaveLength(0);
356				expect(pending[0]?.summary.videoUrl).toBeUndefined();
357			});
358	
359			it("getPendingCatchUpCards returns only the pending items' live review cards", () => {
360				completeLessonsUpTo(22);
361				deleteCardsStartingWith("ฤ:");
362				service.reconcileCards();
363	
364				const cards = service.getPendingCatchUpCards(22);
365				expect(cards.length).toBeGreaterThan(0);
366				expect(cards.every((c) => c.id.startsWith("ฤ:"))).toBe(true);
367			});
368	
369			it("returns no cards for a lesson with nothing pending", () => {
370				completeLessonsUpTo(22);
371				expect(service.getPendingCatchUpCards(22)).toHaveLength(0);
372			});
373	
374			it("dismissPendingCatchUp clears the pending entry", () => {
375				completeLessonsUpTo(22);
376				deleteCardsStartingWith("ฤ:");
377				service.reconcileCards();
378				expect(service.getPendingCatchUps()).toHaveLength(1);
379	
380				service.dismissPendingCatchUp(22);
381	
382				expect(service.getPendingCatchUps()).toHaveLength(0);
383			});
384		});
385	});
