1	import { describe, expect, it } from "vitest";
2	import type {
3		LearnerState,
4		PropertyCard,
5		SessionSummary,
6	} from "../../domain/shared/types";
7	import {
8		DEFAULT_SRS_DATA,
9		INITIAL_LEARNER_STATE,
10	} from "../../domain/shared/types";
11	import { mergeLearnerStates } from "./MergeService";
12	
13	function makeCard(
14		id: string,
15		repetitions: number,
16		lessonNumber = 1,
17	): PropertyCard {
18		return {
19			id,
20			symbolCharacter: "ก",
21			property: "recognition",
22			question: `What is ${id}?`,
23			correctAnswer: "answer",
24			choices: ["a", "b", "c", "answer"],
25			srs: {
26				...DEFAULT_SRS_DATA,
27				repetitions,
28				nextReviewDate: new Date().toISOString(),
29			},
30			lessonNumber,
31		};
32	}
33	
34	function makeSession(id: string): SessionSummary {
35		return {
36			sessionId: id,
37			completedAt: new Date().toISOString(),
38			type: "lesson",
39			durationMs: 1000,
40			totalCards: 5,
41			correctCount: 4,
42			incorrectCount: 1,
43			accuracy: 80,
44			newCardsGraduated: 3,
45		};
46	}
47	
48	describe("mergeLearnerStates", () => {
49		it("merges two empty states", () => {
50			const result = mergeLearnerStates(
51				INITIAL_LEARNER_STATE,
52				INITIAL_LEARNER_STATE,
53			);
54			expect(result).toEqual(INITIAL_LEARNER_STATE);
55		});
56	
57		it("unions completedLessons without duplicates", () => {
58			const current: LearnerState = {
59				...INITIAL_LEARNER_STATE,
60				completedLessons: [1, 2, 3],
61			};
62			const incoming: LearnerState = {
63				...INITIAL_LEARNER_STATE,
64				completedLessons: [2, 3, 4, 5],
65			};
66			const result = mergeLearnerStates(current, incoming);
67			expect(result.completedLessons.sort()).toEqual([1, 2, 3, 4, 5]);
68		});
69	
70		it("preserves current.currentLesson", () => {
71			const current: LearnerState = {
72				...INITIAL_LEARNER_STATE,
73				currentLesson: 3,
74			};
75			const incoming: LearnerState = {
76				...INITIAL_LEARNER_STATE,
77				currentLesson: 7,
78			};
79			const result = mergeLearnerStates(current, incoming);
80			expect(result.currentLesson).toBe(3);
81		});
82	
83		it("preserves current.apprenticeLimits, not incoming's", () => {
84			const current: LearnerState = {
85				...INITIAL_LEARNER_STATE,
86				apprenticeLimits: { general: 42, script: 10, sentence: 20 },
87			};
88			const incoming: LearnerState = {
89				...INITIAL_LEARNER_STATE,
90				apprenticeLimits: { general: 999, script: 999, sentence: 999 },
91			};
92			const result = mergeLearnerStates(current, incoming);
93			expect(result.apprenticeLimits).toEqual({
94				general: 42,
95				script: 10,
96				sentence: 20,
97			});
98		});
99	
100		it("leaves apprenticeLimits undefined when current never set it", () => {
101			const current: LearnerState = { ...INITIAL_LEARNER_STATE };
102			const incoming: LearnerState = {
103				...INITIAL_LEARNER_STATE,
104				apprenticeLimits: { general: 999, script: 999, sentence: 999 },
105			};
106			const result = mergeLearnerStates(current, incoming);
107			expect(result.apprenticeLimits).toBeUndefined();
108		});
109	
110		it("includes cards only in current", () => {
111			const current: LearnerState = {
112				...INITIAL_LEARNER_STATE,
113				cards: { a: makeCard("a", 2) },
114			};
115			const incoming: LearnerState = { ...INITIAL_LEARNER_STATE, cards: {} };
116			const result = mergeLearnerStates(current, incoming);
117			expect(result.cards.a.srs.repetitions).toBe(2);
118		});
119	
120		it("includes cards only in incoming", () => {
121			const current: LearnerState = { ...INITIAL_LEARNER_STATE, cards: {} };
122			const incoming: LearnerState = {
123				...INITIAL_LEARNER_STATE,
124				cards: { b: makeCard("b", 5) },
125			};
126			const result = mergeLearnerStates(current, incoming);
127			expect(result.cards.b.srs.repetitions).toBe(5);
128		});
129	
130		it("keeps the card with higher repetitions on conflict", () => {
131			const current: LearnerState = {
132				...INITIAL_LEARNER_STATE,
133				cards: { x: makeCard("x", 3) },
134			};
135			const incoming: LearnerState = {
136				...INITIAL_LEARNER_STATE,
137				cards: { x: makeCard("x", 7) },
138			};
139			const result = mergeLearnerStates(current, incoming);
140			expect(result.cards.x.srs.repetitions).toBe(7);
141		});
142	
143		it("keeps current card when repetitions are equal", () => {
144			const currentCard = makeCard("x", 3);
145			currentCard.correctAnswer = "current";
146			const incomingCard = makeCard("x", 3);
147			incomingCard.correctAnswer = "incoming";
148			const current: LearnerState = {
149				...INITIAL_LEARNER_STATE,
150				cards: { x: currentCard },
151			};
152			const incoming: LearnerState = {
153				...INITIAL_LEARNER_STATE,
154				cards: { x: incomingCard },
155			};
156			const result = mergeLearnerStates(current, incoming);
157			expect(result.cards.x.correctAnswer).toBe("current");
158		});
159	
160		it("unions achievements without duplicates", () => {
161			const current: LearnerState = {
162				...INITIAL_LEARNER_STATE,
163				achievements: ["first_review", "century"],
164			};
165			const incoming: LearnerState = {
166				...INITIAL_LEARNER_STATE,
167				achievements: ["century", "warrior"],
168			};
169			const result = mergeLearnerStates(current, incoming);
170			expect(result.achievements.sort()).toEqual([
171				"century",
172				"first_review",
173				"warrior",
174			]);
175		});
176	
177		it("merges empty achievements correctly", () => {
178			const result = mergeLearnerStates(
179				INITIAL_LEARNER_STATE,
180				INITIAL_LEARNER_STATE,
181			);
182			expect(result.achievements).toEqual([]);
183		});
184	
185		it("deduplicates sessionHistory by sessionId", () => {
186			const s1 = makeSession("s1");
187			const s2 = makeSession("s2");
188			const s3 = makeSession("s3");
189			const current: LearnerState = {
190				...INITIAL_LEARNER_STATE,
191				sessionHistory: [s1, s2],
192			};
193			const incoming: LearnerState = {
194				...INITIAL_LEARNER_STATE,
195				sessionHistory: [s2, s3],
196			};
