		this.cacheRaw = raw;
		return this.cache;
	}

	save(state: LearnerState): void {
		const raw = JSON.stringify(state);
		// Adopt what was just saved as the cache, keyed on the very string
		// written, so the next `load` is a string compare rather than a parse.
