/**
 * Resolves a 1-based position to its declared sequence entry. Positions are
 * assigned from declaration order, so the entry at index `position - 1` is
 * exactly the one whose `position` matches.
 */
function entryAt(position: number): LessonSequenceEntry | undefined {
	return lessonSequence[position - 1];
}

export interface LessonInfo {
	lessonNumber: number;
	title: string;
	focus: string;
	cards: PropertyCard[];
}

export interface ConsonantSummary {
	character: string;
	name: string;
	nameRomanized: string;
	nameMeaning: string;
	classType: string;
	initialSound: string;
	finalSound: string;
	hasDeadEnding: boolean;
	isAspirated: boolean;
	mnemonic?: string;
	audioUrl?: string;
}

export interface VowelSummary {
	character: string;
	name: string;
	sound: string;
	length: string;
	position: string;
	mnemonic?: string;
	audioUrl?: string;
}

export interface ToneMarkSummary {
	character: string;
	name: string;
	midClassTone: string;
	highClassTone: string | null;
	lowClassTone: string | null;
	audioUrl?: string;
}

export interface RareVowelSummary {
	character: string;
	name: string;
	pronunciation: string;
	length: string;
	notes: string;
}

export interface NumeralSummary {
	character: string;
	arabic: number;
	word: string;
	romanization: string;
}

export interface ToneRuleSummary {
	id: string;
	description: string;
}

export interface LessonSummary {
	lessonNumber: number;
	title: string;
	focus: string;
	videoUrl?: string;
	consonants: ConsonantSummary[];
	vowels: VowelSummary[];
	toneMarks: ToneMarkSummary[];
	rareVowels: RareVowelSummary[];
	numerals: NumeralSummary[];
	toneRules: ToneRuleSummary[];
}

function toEntity(dto: PropertyCard): ScriptPropertyCard {
	return new ScriptPropertyCard(
		dto.id,
		dto.question,
		dto.correctAnswer,
		dto.choices,
		SrsSchedule.fromDTO(dto.srs),
		dto.symbolCharacter,
		dto.property,
		dto.lessonNumber,
		dto.audioUrl,
		dto.consonantClass,
	);
}

