	// No `consonantClass` here: this card's question IS "what class is this
	// consonant", so the glyph must render with no color hint.
	const classCard: PropertyCard = {
		id: `${c.character}:class`,
		symbolCharacter: c.character,
		audioUrl: c.audioUrl,
