function generateToneRuleCard(rule: ToneRule): PropertyCard {
	const question = `${rule.consonantClass} class consonant + ${rule.syllableType} syllable = what tone?`;

	return {
		id: `tone-rule:${rule.id}`,
		symbolCharacter: "",
		property: "toneRule",
