const numeralRomanizationPool = thaiNumerals.map((n) => n.romanization);

// ---------------------------------------------------------------------------
// Utility: Pick multiple-choice options
// ---------------------------------------------------------------------------

function pickChoices(correct: string, pool: string[], count = 4): string[] {
	const distractors = pool.filter((item) => item !== correct);
	const needed = Math.min(count - 1, distractors.length);

	// Fisher-Yates partial shuffle to pick `needed` items
	const copy = [...distractors];
	for (let i = copy.length - 1; i > copy.length - 1 - needed && i > 0; i--) {
		const j = Math.floor(Math.random() * (i + 1));
		[copy[i], copy[j]] = [copy[j] as string, copy[i] as string];
	}
	const picked = copy.slice(copy.length - needed);

	// Combine with correct answer and shuffle
	const choices = [...picked, correct];
	for (let i = choices.length - 1; i > 0; i--) {
		const j = Math.floor(Math.random() * (i + 1));
		[choices[i], choices[j]] = [choices[j] as string, choices[i] as string];
	}

	return choices;
}

// ---------------------------------------------------------------------------
// Lesson identity
// ---------------------------------------------------------------------------

/**
 * `symbols.ts` still keys its `lesson` fields on the pre-migration integers;
 * a card is stamped with the declared sequence's *position* for that lesson
 * (`PropertyCard.lessonNumber`), so the two stores convert through one
 * mapping. 0 stays 0: it is the "belongs to no lesson" sentinel.
 */
function teachingPosition(symbolLesson: number | undefined): number {
	if (symbolLesson == null) return 0;
	return lessonEntryByNumber(symbolLesson)?.position ?? 0;
}

/** The `symbols.ts` lesson key for a 1-based position in the declared sequence. */
function legacyNumberAt(position: number): number | undefined {
	return lessonSequence[position - 1]?.legacyNumber;
}

