		if (
			this.apprenticeService &&
			!this.apprenticeService.canStartLesson("vocab")
		) {
			return null;
		}

		const words = this.getUnlearnedWords();
		if (words.length === 0) return null;
		return { words: words.slice(0, BATCH_SIZE) };
	}

