interface LessonPathProps {
	totalLessons: number;
	completedLessons: Set<number>;
	nextAvailable: number | null;
	onLessonClick: (n: number) => void;
}

const NODE_R = 22;
const SPACING_X = 90;
const SPACING_Y = 72;
const COLS = 3;

export function LessonPath({
	totalLessons,
	completedLessons,
	nextAvailable,
